Certify a Vaccination.code:
// Request a vaccination certificate.
// POST /v1/certify takes an array of certification requests.
certifyVaccination([
  {
    // Code issued when the recipient pre-enrolled.
    preEnrollmentCode: $.data.preEnrollmentCode,
    recipient: {
      name: 'Grace Banda',
      dob: '1988-07-14',
      gender: 'Female',
      nationality: 'Malawian',
      // ID type and number, e.g. 'did:in.gov.uidai.aadhaar:123456789012'.
      identity: $.data.identity,
      contact: ['tel:+265999000000'],
      address: {
        addressLine1: 'Area 25',
        addressLine2: '',
        district: 'Lilongwe',
        state: 'Central Region',
        pincode: 207203,
      },
    },
    vaccination: {
      name: 'COVID-19 Vaccine',
      batch: $.data.batchNumber,
      manufacturer: 'Serum Institute of India',
      date: $.data.vaccinatedAt,
      effectiveStart: '2026-11-02',
      effectiveUntil: '2027-11-02',
      dose: 1,
      totalDoses: 2,
    },
    vaccinator: { name: $.data.vaccinatorName },
    facility: {
      name: 'Kamuzu Central Hospital',
      address: {
        addressLine1: 'Mzimba Street',
        addressLine2: '',
        district: 'Lilongwe',
        state: 'Central Region',
        pincode: 207203,
      },
    },
    meta: {},
  },
]);

Certify Vaccinations in Bulk.code:
// Certify a batch of vaccinations from an incoming list.
certifyVaccination(state =>
  state.data.vaccinations.map(v => ({
    preEnrollmentCode: v.enrollment_code,
    recipient: {
      name: v.full_name,
      dob: v.date_of_birth,
      gender: v.sex,
      nationality: v.nationality,
      identity: v.national_id,
      contact: [`tel:${v.phone}`],
      address: { addressLine1: v.village, district: v.district, state: v.region, pincode: v.postcode },
    },
    vaccination: {
      name: v.vaccine,
      batch: v.batch,
      manufacturer: v.manufacturer,
      date: v.vaccinated_at,
      dose: v.dose_number,
      totalDoses: v.total_doses,
    },
    vaccinator: { name: v.vaccinator },
    facility: { name: v.facility_name, address: { district: v.district, state: v.region } },
    meta: { source: 'district-immunisation-register' },
  }))
);
